-- Safely import the complete 70-message catalog into private management review.
-- Every imported scenario remains DRAFT until operations, legal and provider review.
insert into public.landshop_comm_templates(id,subject,headline,body,whatsapp,sms,state,change_note)
select x.id,x.subject,x.headline,x.body,x.whatsapp,x.sms,'draft',left(x.change_note,490)
from jsonb_to_recordset('[{"id":"C01","subject":"Your Landshop {{plan}} application has been received","headline":"Your journey starts here.","body":"We’ve received your {{plan}} application for {{property}}. Your reference is {{application_ref}}.\n\nWe’ll keep you informed as the team reviews the details. Track your progress securely, whenever it suits you.","whatsapp":"Hello {{first_name}}, Landshop has received application {{application_ref}} for {{plan}}. Check your secure dashboard for updates. This is an acknowledgment, not an approval.","sms":"Landshop: Application {{application_ref}} received. Check your dashboard for updates. Approval is pending.","change_note":"Reviewed scenario source: Word: automated welcome mail (adapted), pending exact-event and terms approval"},{"id":"C02","subject":"Your {{plan}} assessment is approved","headline":"A lovely step forward.","body":"Your {{plan}} assessment has been approved. Congratulations on reaching this important milestone.\n\nYour official terms and any outstanding conditions are ready for careful review in your secure account.","whatsapp":"Good news, {{first_name}}. Your {{plan}} assessment has been approved. Review the official terms in your secure Landshop dashboard. Do not pay from an unverified link.","sms":"Landshop: {{plan}} assessment approved for ref {{application_ref}}. Review the official terms in your dashboard.","change_note":"Reviewed scenario source: Word: assessment / evaluation status update (adapted), pending exact-event and terms approval"},{"id":"C03","subject":"Your Landshop property inspection is confirmed","headline":"Your visit is confirmed.","body":"Your inspection of {{property}} is booked for {{inspection_date}} at {{inspection_time}} WAT.\n\nWe look forward to showing you around. Your meeting instructions and any rescheduling options are available in your booking.","whatsapp":"Landshop inspection confirmed: {{property}}, {{inspection_date}} at {{inspection_time}} WAT. Ref {{booking_ref}}. Manage or reschedule via your secure booking page.","sms":"Landshop inspection: {{inspection_date}} {{inspection_time}} WAT. Ref {{booking_ref}}. View booking details in your dashboard.","change_note":"Reviewed scenario source: Word: scheduled inspection notice (adapted), pending exact-event and terms approval"},{"id":"C04","subject":"Your offer letter for {{property}} is ready to review","headline":"Your offer is ready.","body":"Your offer letter for {{property}} is available to review.\n\nPlease read the pricing, conditions and validity period before you sign. We’re here to answer any questions.","whatsapp":"Hello {{first_name}}, your Landshop offer letter for {{property}} is ready. Please sign in to your secure dashboard to review the terms before signing.","sms":"Landshop: Offer letter for {{property}} is ready in your secure dashboard. Review all terms before signing.","change_note":"Reviewed scenario source: Word: notice of offer letter (adapted), pending exact-event and terms approval"},{"id":"C05","subject":"Payment received: {{payment_amount}} for {{property}}","headline":"Payment received. Thank you.","body":"Your instalment of {{payment_amount}} has been reconciled for {{property}}.\n\nYour receipt and updated balance are available in your account. We appreciate your commitment.","whatsapp":"Landshop confirms a reconciled instalment of {{payment_amount}} for {{property}} (ref {{payment_ref}}). View your receipt and balance in your secure dashboard.","sms":"Landshop receipt: {{payment_amount}} received. Ref {{payment_ref}}. View updated statement in your account.","change_note":"Reviewed scenario source: Word: payment confirmation (instalment), 2023 sample made dynamic, pending exact-event and terms approval"},{"id":"C06","subject":"Your full payment for {{property}} is confirmed","headline":"A milestone worth celebrating.","body":"We’ve verified your full payment for {{property}}. Thank you for trusting Landshop.\n\nYour documentation and transfer steps will appear in your account as they are confirmed.","whatsapp":"Hello {{first_name}}, your full payment for {{property}} has been confirmed (ref {{payment_ref}}). Check your dashboard for documentation updates.","sms":"Landshop: Full payment recorded, ref {{payment_ref}}. Next document steps are available in your dashboard.","change_note":"Reviewed scenario source: Word: payment confirmation (outright), adapted, pending exact-event and terms approval"},{"id":"C07","subject":"Your contract of sale for {{property}} is ready","headline":"Your contract is ready.","body":"Your contract of sale for {{property}} is ready to review.\n\nTake your time with the details, ask questions and follow the secure signing instructions when you are comfortable.","whatsapp":"Landshop: Your contract of sale for {{property}} is ready. Review it securely in your dashboard. Contact our documentation team with questions.","sms":"Landshop contract ready for {{property}}. Review it in your secure account before signing.","change_note":"Reviewed scenario source: Word: communication of document readiness (adapted), pending exact-event and terms approval"},{"id":"C08","subject":"Your Landshop mortgage estimate is ready","headline":"Your estimate, made simple.","body":"Here is the mortgage estimate you asked us to save.\n\nIt’s a helpful planning illustration, not a financing offer. You can revisit the figures or speak with an adviser at any time.","whatsapp":"Your requested Landshop estimate is ready. View it in your secure link or dashboard. This is an illustration only, not mortgage approval.","sms":"Landshop: Your requested estimate is ready. Check your email or dashboard. Figures are indicative.","change_note":"Reviewed scenario source: Proposed: calculator delivery, pending exact-event and terms approval"},{"id":"C09","subject":"Welcome to Landshop, {{first_name}}","headline":"Welcome to what’s possible.","body":"Thank you for joining Landshop Insights. We’re glad you’re here.\n\nLook forward to thoughtful property guidance, helpful ownership ideas and updates you can opt out of whenever you choose.","whatsapp":"Welcome to Landshop, {{first_name}}. Thanks for opting in to property insights and mortgage guidance. Reply STOP to opt out.","sms":"Welcome to Landshop updates. Reply STOP to opt out.","change_note":"Reviewed scenario source: Proposed: opted-in welcome, not anonymous-exit email, pending exact-event and terms approval"},{"id":"C10","subject":"Would you like help interpreting your mortgage estimate?","headline":"Need a hand with the numbers?","body":"Your mortgage estimate is a starting point. If you’d like clarity on deposits, eligibility or repayments, our advisers can help.\n\nContinue at your pace, with no pressure to decide.","whatsapp":"Hello {{first_name}}, would you like help understanding your Landshop mortgage estimate? Choose a convenient time in your account. Reply STOP to opt out.","sms":"Landshop: Need help with your mortgage estimate? Book an adviser in your account. STOP to opt out.","change_note":"Reviewed scenario source: Proposed: opt-in nurture, pending exact-event and terms approval"},{"id":"C11","subject":"Your Landshop application draft is saved","headline":"Pick up where you left off.","body":"Your {{plan}} application for {{property}} is saved as a draft.\n\nContinue whenever you’re ready. No assessment has started until you submit it.","whatsapp":"Hi {{first_name}}, your {{plan}} application is saved but not submitted. Resume securely in your Landshop account. Reply STOP to opt out.","sms":"","change_note":"Reviewed scenario source: Proposed: incomplete application, pending exact-event and terms approval"},{"id":"C12","subject":"Action needed: {{application_ref}} requires information","headline":"One more thing to complete.","body":"Your application {{application_ref}} needs a little more information before the review can continue.\n\nSign in to view the exact requirements and upload documents safely.","whatsapp":"Landshop needs an update for application {{application_ref}}. Sign in to view the outstanding documents and upload securely.","sms":"Landshop application {{application_ref}}: additional documents requested. See dashboard.","change_note":"Reviewed scenario source: Proposed: assessment workflow, pending exact-event and terms approval"},{"id":"C13","subject":"An update on your Landshop application {{application_ref}}","headline":"Your next steps are here.","body":"We’re unable to approve application {{application_ref}} at this stage. Thank you for taking the time to apply.\n\nYour secure account explains any available corrections, review options or alternatives.","whatsapp":"Hello {{first_name}}, your application {{application_ref}} was not approved at this stage. Please see your dashboard for review or reapplication options.","sms":"Landshop {{application_ref}}: application not approved at this stage. Secure next steps in dashboard.","change_note":"Reviewed scenario source: Xtra + Beta diagrams: failed / reapplication, pending exact-event and terms approval"},{"id":"C14","subject":"Reminder: your property inspection is tomorrow","headline":"See you tomorrow.","body":"A gentle reminder: your inspection of {{property}} is scheduled for {{inspection_date}} at {{inspection_time}} WAT.\n\nWe look forward to welcoming you. Need a different time? You can manage the booking securely.","whatsapp":"Landshop reminder: {{property}} inspection is {{inspection_date}} at {{inspection_time}} WAT. See secure booking details or reschedule.","sms":"Landshop inspection reminder: {{inspection_date}} {{inspection_time}} WAT. Booking {{booking_ref}}.","change_note":"Reviewed scenario source: Mortgage Xtra diagram: inspection reminder, pending exact-event and terms approval"},{"id":"C15","subject":"Thank you for inspecting {{property}}","headline":"It was lovely to meet you.","body":"Thank you for inspecting {{property}} with our team.\n\nIf you’d like to review the documents, compare choices or ask another question, we’re happy to help.","whatsapp":"Hello {{first_name}}, thank you for inspecting {{property}}. Questions about documents or next steps? Reply to speak with your adviser. STOP to opt out.","sms":"","change_note":"Reviewed scenario source: Proposed: post-inspection nurture, pending exact-event and terms approval"},{"id":"C16","subject":"Reminder: review your Landshop offer before {{due_date}}","headline":"A gentle offer reminder.","body":"The current offer for {{property}} is awaiting your response and is scheduled to expire on {{due_date}}.\n\nPlease review every term before making your decision.","whatsapp":"Landshop: Your offer for {{property}} has a stated deadline of {{due_date}}. Review securely or speak with your adviser.","sms":"","change_note":"Reviewed scenario source: Proposed: offer lifecycle, pending exact-event and terms approval"},{"id":"C17","subject":"Your verified Landshop payment instructions are available","headline":"Your payment details are ready.","body":"Verified funding instructions for {{property}} are now available in your Landshop account.\n\nAlways confirm the beneficiary and amount inside the secure portal before transferring funds.","whatsapp":"Landshop: Verified funding instructions for {{property}} are available in your secure account. Confirm details there before paying.","sms":"Landshop: Check your secure account for approved payment instructions. Ref {{application_ref}}.","change_note":"Reviewed scenario source: Mortgage Xtra + Beta diagrams: account creation/funding, pending exact-event and terms approval"},{"id":"C18","subject":"An update on your {{property}} documents","headline":"Your documents have progressed.","body":"There’s a new documentation update for {{property}}.\n\nYour account shows the verified stage, any outstanding action and the latest confirmed information.","whatsapp":"Landshop documentation update for {{property}}: {{document_stage}}. Review details in your account.","sms":"","change_note":"Reviewed scenario source: Proposed: document status, pending exact-event and terms approval"},{"id":"C19","subject":"Still exploring property options? We can help","headline":"Still exploring? We’re here.","body":"A good property decision deserves careful thought.\n\nWhenever you’re ready, our team can help you compare ownership options and find the right next step.","whatsapp":"Hi {{first_name}}, still exploring property options? Landshop can help you compare your choices. Reply STOP to opt out.","sms":"","change_note":"Reviewed scenario source: Proposed: limited nurture; not perpetual messaging, pending exact-event and terms approval"},{"id":"X01","subject":"Meet your Landshop Mortgage Xtra support team","headline":"Your adviser is here to help.","body":"Your Mortgage Xtra application {{application_ref}} has reached Client Service.\n\nYour assigned Landshop adviser will guide you through the next steps. Find the verified contact in your account.","whatsapp":"Hello {{first_name}}, Mortgage Xtra case {{application_ref}} has been assigned to Client Service. Please check your account for the next steps.","sms":"","change_note":"Reviewed scenario source: Mortgage Xtra diagram: customer service, pending exact-event and terms approval"},{"id":"X02","subject":"Other property options that may suit your plan","headline":"More options, more possibilities.","body":"Not every property is the perfect fit. We can help you compare genuine, verified alternatives to suit your priorities.\n\nYour adviser can share the available options without pressure.","whatsapp":"Hi {{first_name}}, your adviser has alternative verified property options for Mortgage Xtra. Would you like the comparison? Reply STOP to opt out.","sms":"","change_note":"Reviewed scenario source: Mortgage Xtra diagram: prospect alternatives / incentives, pending exact-event and terms approval"},{"id":"X03","subject":"Mortgage Xtra: your equity milestone is approaching","headline":"Your equity milestone is near.","body":"A payment milestone for {{property}} is approaching on {{due_date}}.\n\nPlease check the exact equity amount, approved schedule and banking details in your signed agreement and account.","whatsapp":"Landshop Mortgage Xtra: equity milestone of {{payment_amount}} is due {{due_date}} under your signed agreement. Verify in your dashboard.","sms":"Landshop Xtra equity due {{due_date}}: {{payment_amount}}. Verify payment details in your dashboard.","change_note":"Reviewed scenario source: Mortgage Xtra diagram: payment of 30% equity, pending exact-event and terms approval"},{"id":"X04","subject":"Your Mortgage Xtra equity payment has been confirmed","headline":"Your equity payment is confirmed.","body":"We’ve verified the payment recorded against your Mortgage Xtra equity milestone for {{property}}.\n\nYour updated statement and next official milestone are ready to view.","whatsapp":"Landshop: Your Mortgage Xtra equity milestone is confirmed ({{payment_ref}}). View your updated statement and next stage in your dashboard.","sms":"","change_note":"Reviewed scenario source: Mortgage Xtra diagram: payment confirmation and approval notice, pending exact-event and terms approval"},{"id":"X05","subject":"Your Mortgage Xtra property progress update","headline":"Your property update is here.","body":"The project team has recorded a new milestone for {{property}}.\n\nReview the verified status and current expected date. Timelines remain subject to your signed agreement.","whatsapp":"Landshop Mortgage Xtra update: {{document_stage}} is expected {{due_date}} subject to your verified agreement. See dashboard for details.","sms":"","change_note":"Reviewed scenario source: Mortgage Xtra diagram: notice of approval within 90 days, pending exact-event and terms approval"},{"id":"X06","subject":"Your property handover appointment is ready","headline":"Ready for the next chapter.","body":"Your property handover process for {{property}} is ready to progress.\n\nYour account has the confirmed appointment and document checklist, where applicable.","whatsapp":"Congratulations {{first_name}}. Your property handover step for {{property}} is ready. Verify your appointment and documents in the Landshop portal.","sms":"Landshop: Property handover step ready for {{property}}. View secure dashboard for details.","change_note":"Reviewed scenario source: Mortgage Xtra diagram: handover of key and documents, pending exact-event and terms approval"},{"id":"X07","subject":"Annual Mortgage Xtra payment reminder for {{property}}","headline":"Your annual account reminder.","body":"Your next Mortgage Xtra payment milestone is approaching on {{due_date}}.\n\nReview the amount and applicable contractual rate in your official schedule before taking action.","whatsapp":"Landshop annual Mortgage Xtra notice: {{payment_amount}} due {{due_date}} for {{property}}, contract year {{contract_year}}. Verify agreement and account.","sms":"Landshop annual due {{due_date}}: {{payment_amount}}. Log in to verify contract and payment details.","change_note":"Reviewed scenario source: Mortgage Xtra diagram: 7% yearly for next 15 years, pending exact-event and terms approval"},{"id":"B01","subject":"We have received your Beta Mortgage pre-application","headline":"Your first step is in.","body":"We’ve received your Beta Mortgage pre-application. Your reference is {{application_ref}}.\n\nWe’ll let you know what is required next. A pre-application is not yet a financing approval.","whatsapp":"Landshop: Beta Mortgage pre-application {{application_ref}} received. Follow your progress in the secure account.","sms":"Landshop Beta: Pre-application received, ref {{application_ref}}. Check account for next steps.","change_note":"Reviewed scenario source: Beta Mortgage diagram: automated welcome email, pending exact-event and terms approval"},{"id":"B02","subject":"Your Beta Mortgage qualification update","headline":"Your qualification update.","body":"There’s an official qualification update for your Beta Mortgage application.\n\nYour account contains the authorized decision and all conditions to review before proceeding.","whatsapp":"Landshop Beta Mortgage: A new qualification decision is available for {{application_ref}}. Review the approved terms in your secure account.","sms":"Landshop Beta: Qualification update for {{application_ref}}. Check official dashboard.","change_note":"Reviewed scenario source: Beta Mortgage diagram: full qualification, pending exact-event and terms approval"},{"id":"B03","subject":"Your Beta Mortgage funding schedule is available","headline":"Your funding plan, clearly.","body":"Your Beta Mortgage funding schedule is now ready for review.\n\nCheck the amounts, dates and applicable terms from your approved agreement before making a commitment.","whatsapp":"Landshop Beta Mortgage: your verified funding schedule for {{property}} is available. Check your account for amounts, dates and terms.","sms":"Landshop Beta funding schedule available in dashboard. Check approved amounts and due dates.","change_note":"Reviewed scenario source: Beta Mortgage diagram: 30% / 6 months / 2.5% language, pending exact-event and terms approval"},{"id":"B04","subject":"Beta Mortgage payment confirmation {{payment_ref}}","headline":"Another payment recorded.","body":"We’ve reconciled your Beta Mortgage payment of {{payment_amount}} for {{property}}.\n\nYour receipt and latest scheduled balance are available securely. Thank you.","whatsapp":"Landshop Beta: {{payment_amount}} received, ref {{payment_ref}}. View payment status and remaining schedule in dashboard.","sms":"Landshop Beta receipt {{payment_ref}}: {{payment_amount}} received. See account.","change_note":"Reviewed scenario source: Beta Mortgage diagram: recurring payment confirmations, pending exact-event and terms approval"},{"id":"B05","subject":"Reminder: your Beta Mortgage payment is due {{due_date}}","headline":"Your next instalment is coming.","body":"A scheduled Beta Mortgage payment of {{payment_amount}} is due on {{due_date}}.\n\nPlease verify the details in your account. If you need assistance, our team can help you review the options.","whatsapp":"Landshop Beta reminder: {{payment_amount}} due {{due_date}} for {{property}}. Verify payment details in your secure account.","sms":"Landshop Beta payment reminder: {{payment_amount}} due {{due_date}}. Check account.","change_note":"Reviewed scenario source: Beta Mortgage diagram: recurring payments, pending exact-event and terms approval"},{"id":"B06","subject":"Your Beta Mortgage payment milestone has been reached","headline":"Your progress is showing.","body":"You’ve reached a verified payment milestone for {{property}} under your Beta Mortgage agreement.\n\nYour account shows what happens next; property readiness remains subject to separate confirmation.","whatsapp":"Landshop Beta update: your payment milestone for {{property}} is recorded. Check your account for the next verified readiness update.","sms":"","change_note":"Reviewed scenario source: Beta Mortgage diagram: at 90% or complete payment notify readiness, pending exact-event and terms approval"},{"id":"B07","subject":"Your Beta Mortgage financing has progressed","headline":"Your financing has progressed.","body":"A verified lender milestone has been recorded for {{property}}.\n\nSee the official financing status in your account. Your signed financing and handover terms remain unchanged.","whatsapp":"Landshop Beta: Your financing milestone has changed to {{loan_status}}. View the verified details in your dashboard.","sms":"Landshop Beta financing status: {{loan_status}}. Check secure dashboard.","change_note":"Reviewed scenario source: Beta Mortgage diagram: loan issued to developer, pending exact-event and terms approval"},{"id":"B08","subject":"Update: expected readiness for {{property}}","headline":"A project readiness update.","body":"There is a new verified readiness update for {{property}}.\n\nPlease check the current project stage and expected date in your account.","whatsapp":"Landshop Beta: {{property}} readiness update is available, including the confirmed current timeline. View dashboard.","sms":"","change_note":"Reviewed scenario source: Beta Mortgage diagram: successful loan application ready in 90 days, pending exact-event and terms approval"},{"id":"B09","subject":"Important: your Beta Mortgage payment needs attention","headline":"A payment needs your attention.","body":"Your account shows a scheduled payment that has not yet been reconciled.\n\nIf you’ve already paid, submit the reference securely. Otherwise, contact Accounts to review your options.","whatsapp":"Landshop Beta: a payment is marked overdue for {{property}}. If already paid, upload proof securely; otherwise contact support to review options.","sms":"Landshop Beta payment alert: review your account for overdue status or reconciliation.","change_note":"Reviewed scenario source: Beta Mortgage diagram: notice of default, pending exact-event and terms approval"},{"id":"B10","subject":"Action required: please review your Beta Mortgage payment status","headline":"Let’s resolve this together.","body":"A payment remains outstanding in your Beta Mortgage account.\n\nPlease review your agreement and contact Accounts. Any grace period or charge applies only when legally and contractually verified.","whatsapp":"Landshop Beta: please review the overdue payment notice in your secure dashboard. Contractual consequences require verification; contact Accounts.","sms":"","change_note":"Reviewed scenario source: Beta Mortgage diagram: 1-month grace and 5% charge, unapproved, pending exact-event and terms approval"},{"id":"B11","subject":"Formal notice regarding your Beta Mortgage agreement","headline":"An important document is ready.","body":"Official correspondence about your Beta Mortgage agreement needs your attention.\n\nRead the signed document securely, including any response period and contact details for the authorized team.","whatsapp":"Landshop: A formal account notice requires your attention. Please securely access the signed document and contact the authorised support team.","sms":"","change_note":"Reviewed scenario source: Beta Mortgage diagram: notice of breach / contract violation, pending exact-event and terms approval"},{"id":"B12","subject":"Your Beta Mortgage account status update","headline":"Your latest mortgage status.","body":"Your updated Beta Mortgage financing status is available.\n\nYour account shows the next verified milestone and any action required from you.","whatsapp":"Landshop Beta: your financing status is {{loan_status}}. Review timeline and next steps in your account.","sms":"","change_note":"Reviewed scenario source: Beta Mortgage diagram: recurring loan updates, pending exact-event and terms approval"},{"id":"I01","subject":"Your Landshop investment application is received","headline":"Welcome to your Invest journey.","body":"Your Landshop investment application {{application_ref}} has been received.\n\nBefore any commitment, review the approved opportunity details, risks and applicable agreements in your account.","whatsapp":"Landshop: We received your Invest application {{application_ref}}. Please review the official next steps in your secure account. No returns are guaranteed.","sms":"Landshop Invest application {{application_ref}} received. Log in for verification and next steps.","change_note":"Reviewed scenario source: INVEST diagram: signup/walk-in → investment application and welcome, pending exact-event and terms approval"},{"id":"I02","subject":"Your Landshop investment has been recorded","headline":"Your investment is recorded.","body":"We’ve reconciled {{payment_amount}} against your signed Landshop investment agreement.\n\nYour receipt, terms and approved reporting schedule are ready. Future returns are not guaranteed.","whatsapp":"Landshop Invest: {{payment_amount}} received and reconciled, ref {{payment_ref}}. Your official investment breakdown is in your secure account.","sms":"Landshop Invest receipt: {{payment_ref}}. Check dashboard for payment breakdown.","change_note":"Reviewed scenario source: INVEST diagram: automated welcome, payment confirmation and breakdown of investment and ROI, pending exact-event and terms approval"},{"id":"I03","subject":"Your monthly Landshop Invest update","headline":"Your monthly update is here.","body":"A verified monthly report for {{property}} is ready.\n\nSee the project activity, current status and any material updates in your secure statement.","whatsapp":"Landshop Invest monthly update for {{property}} is available. Review status and verified details securely.","sms":"","change_note":"Reviewed scenario source: INVEST diagram: monthly updates on investment status and breakdown, pending exact-event and terms approval"},{"id":"I04","subject":"Your quarterly Landshop Invest statement is available","headline":"Your quarterly statement is ready.","body":"Your latest quarterly Landshop Invest statement has been published.\n\nReview actual performance and any verified distribution shown in the document. This message does not promise a payout.","whatsapp":"Landshop Invest: your quarterly statement is available. Any payment is subject to the verified statement and agreement.","sms":"Landshop Invest quarterly report ready. Review the official statement securely.","change_note":"Reviewed scenario source: INVEST diagram: quarterly ROI payments notification and recommendations, pending exact-event and terms approval"},{"id":"I05","subject":"Your Landshop investment is approaching maturity","headline":"An important maturity update.","body":"Your investment in {{property}} is approaching its contractual maturity date of {{due_date}}.\n\nYour account explains the current process and any requirements.","whatsapp":"Landshop Invest: Your investment is approaching its verified maturity date {{due_date}}. Review next steps securely.","sms":"","change_note":"Reviewed scenario source: INVEST diagram: final payout notification (90 days prior), pending exact-event and terms approval"},{"id":"I06","subject":"Landshop Invest: your final payout has been confirmed","headline":"Your payout is confirmed.","body":"We’ve reconciled the final payout of {{payment_amount}} for {{property}}.\n\nYour completion statement and verified payment reference are available in your account.","whatsapp":"Landshop Invest: Your final payout of {{payment_amount}} has been reconciled. Ref {{payment_ref}}. View your statement in your account.","sms":"Landshop Invest payout {{payment_ref}} confirmed. View your official completion statement.","change_note":"Reviewed scenario source: INVEST diagram: final payout, pending exact-event and terms approval"},{"id":"I07","subject":"Your Landshop communication preferences are updated","headline":"Your preferences are updated.","body":"You’ve successfully opted out of optional investment marketing messages.\n\nEssential notices may continue where required for an active agreement. Your investment itself is unchanged.","whatsapp":"Landshop: Your optional Invest updates have been stopped. This does not change any active investment agreement.","sms":"Landshop Invest marketing preferences updated. See dashboard for details.","change_note":"Reviewed scenario source: INVEST diagram: opt out branch; adapted to separate communication preference and contract exit, pending exact-event and terms approval"},{"id":"I08","subject":"Would you like help completing your investment enquiry?","headline":"Still considering an investment?","body":"Your Invest enquiry is saved if you’d like to continue.\n\nOur team can explain verified documentation and risks before you decide. There’s no obligation to proceed.","whatsapp":"Hi {{first_name}}, would you like help completing your Landshop Invest enquiry? There is no obligation. Reply STOP to opt out.","sms":"","change_note":"Reviewed scenario source: Proposed: abandoned investment application follow-up, pending exact-event and terms approval"},{"id":"I09","subject":"Your Landshop investment payment is being checked","headline":"Your payment is being checked.","body":"A payment attempt linked to {{application_ref}} is still awaiting verification.\n\nPlease check its status in your account before retrying or making another transfer.","whatsapp":"Landshop Invest: Payment is pending verification. Please check your secure dashboard before retrying.","sms":"","change_note":"Reviewed scenario source: Proposed: pending/failed funding path, pending exact-event and terms approval"},{"id":"E01","subject":"Welcome to Landshop Estate Pro, {{first_name}}","headline":"Welcome to Estate Pro.","body":"Thank you for your Estate Pro enquiry, {{first_name}}. We’ve received your onboarding request {{application_ref}}.\n\nWe’ll guide you through the verified next steps and introduce your officer when assigned.","whatsapp":"Welcome to Landshop Estate Pro. Your onboarding ref {{application_ref}} was received. Watch for your verified account-officer introduction.","sms":"Landshop Estate Pro onboarding received: {{application_ref}}.","change_note":"Reviewed scenario source: ESTATE PRO diagram: website onboarding and automated welcome, pending exact-event and terms approval"},{"id":"E02","subject":"Your Estate Pro account officer has been assigned","headline":"Your officer has been assigned.","body":"Your Estate Pro account officer is {{account_officer}}.\n\nYou can confirm their official details and continue your enquiry securely in your account.","whatsapp":"Landshop Estate Pro: your assigned account officer is {{account_officer}}. Confirm official contact details in your secure dashboard.","sms":"Landshop Estate Pro: account officer assigned. Sign in to view contact details.","change_note":"Reviewed scenario source: ESTATE PRO diagram: after waiting three days update prospect with account officer, pending exact-event and terms approval"},{"id":"E03","subject":"Were you able to connect with your Estate Pro officer?","headline":"Just checking in.","body":"Were you able to connect with your Estate Pro officer?\n\nIf you still need help, we’ll gladly arrange a convenient follow-up.","whatsapp":"Hello {{first_name}}, were you able to connect with your Estate Pro account officer? Reply here for assistance. Official details are in your dashboard.","sms":"","change_note":"Reviewed scenario source: ESTATE PRO diagram: wait 24 hours and follow-up by call/text, pending exact-event and terms approval"},{"id":"E04","subject":"A little more information is needed for Estate Pro","headline":"A small step remains.","body":"There’s one more requirement to complete your Estate Pro request {{application_ref}}.\n\nSign in to see what’s needed and submit information securely.","whatsapp":"Landshop Estate Pro: More information is required for application {{application_ref}}. Please sign in securely.","sms":"","change_note":"Reviewed scenario source: Proposed: Estate Pro incomplete-information branch, pending exact-event and terms approval"},{"id":"D01","subject":"Welcome to Landshop DEVELOP","headline":"Welcome to Landshop Develop.","body":"Thank you for exploring property with Landshop Develop. We’ve recorded your enquiry {{application_ref}}.\n\nOur team can help you explore verified options and inspections.","whatsapp":"Welcome to Landshop DEVELOP, {{first_name}}. Your enquiry {{application_ref}} was received. A verified adviser will share next steps.","sms":"Landshop DEVELOP enquiry {{application_ref}} received.","change_note":"Reviewed scenario source: DEVELOP diagram: website sign up / walk in and welcome message, pending exact-event and terms approval"},{"id":"D02","subject":"Your Landshop DEVELOP inspection is booked","headline":"Your inspection is all set.","body":"We’ve confirmed your inspection of {{property}} for {{inspection_date}} at {{inspection_time}} WAT.\n\nYour booking details and verified meeting point are available securely.","whatsapp":"Landshop DEVELOP inspection confirmed: {{inspection_date}}, {{inspection_time}} WAT. Ref {{booking_ref}}. Manage appointment in your account.","sms":"Landshop inspection confirmed {{inspection_date}} {{inspection_time}} WAT. Ref {{booking_ref}}.","change_note":"Reviewed scenario source: DEVELOP diagram: inspection confirmation, pending exact-event and terms approval"},{"id":"D03","subject":"Your property inspection is in six hours","headline":"We’ll see you soon.","body":"Your inspection of {{property}} is coming up at {{inspection_time}} WAT.\n\nHere’s a friendly reminder to check your meeting instructions. You can reschedule if needed.","whatsapp":"Reminder: Your Landshop inspection is in 6 hours on {{inspection_date}} at {{inspection_time}} WAT. Need to reschedule? Use your secure booking link.","sms":"Landshop inspection reminder: {{inspection_time}} WAT today. Reschedule via your booking page.","change_note":"Reviewed scenario source: DEVELOP diagram: inspection reminder (6hrs to inspection), pending exact-event and terms approval"},{"id":"D04","subject":"We missed you at your Landshop inspection","headline":"Shall we find another time?","body":"We missed you at the scheduled inspection of {{property}}. We understand plans change.\n\nChoose another available time whenever you’re ready.","whatsapp":"Hi {{first_name}}, we missed you at the Landshop inspection. Would you like to reschedule? Use your secure booking link.","sms":"","change_note":"Reviewed scenario source: DEVELOP diagram: missed inspection and reschedule, pending exact-event and terms approval"},{"id":"D05","subject":"Thank you for visiting {{property}}","headline":"Thank you for visiting.","body":"It was a pleasure helping you explore {{property}}.\n\nIf you’d like clearer pricing, documentation or payment options, your adviser is available to help.","whatsapp":"Thank you for inspecting {{property}}. Would you like a verified property information pack or to discuss next steps with your Landshop adviser?","sms":"","change_